/**
 * Measures Angular's public API surface and the stability tiers declared on it, and checks the
 * conventions that keep the two in agreement. Writes
 * `docs/codebase-map/generated/api-surface.md`.
 *
 * Two independent records describe the public API, and they answer different questions:
 *
 *  - **The goldens** (`goldens/public-api/**​/*.api.md`) are generated by API Extractor from the
 *    built `.d.ts` and reviewed in every PR. They are the authority on *what is exported*: a
 *    symbol cannot enter or leave the public surface without a golden diff. Their release tags
 *    are limited to `@public` and `@deprecated`.
 *
 *  - **The JSDoc tags in source** (`@publicApi`, `@developerPreview`, `@experimental`,
 *    `@deprecated`) are what the angular.dev docs pipeline reads (see
 *    `adev/shared-docs/pipeline/api-gen/manifest/generate_manifest.mts`). They are the authority
 *    on *how stable* a symbol is. Each may carry a version, parsed as the first number in the tag
 *    comment.
 *
 * Because the goldens do not record the stability tiers, promoting an API out of developer
 * preview produces no golden diff. This script surfaces that gap by reporting both sides.
 *
 * Usage:
 *   node docs/codebase-map/tools/analyze-api-surface.mjs
 *
 * Exits non-zero only on a genuine contradiction — a symbol carrying two stability tiers at once.
 * Everything else is reported rather than failed: in particular a `@deprecated` tag without a
 * version is common here and no policy in this repository requires one.
 */

import {readdirSync, readFileSync, writeFileSync, mkdirSync} from 'node:fs';
import {join, relative, sep} from 'node:path';
import {fileURLToPath} from 'node:url';

const REPO_ROOT = fileURLToPath(new URL('../../..', import.meta.url));
const GOLDENS = join(REPO_ROOT, 'goldens', 'public-api');
const PACKAGES = join(REPO_ROOT, 'packages');
const OUT_DIR = join(REPO_ROOT, 'docs', 'codebase-map', 'generated');

/** The stability tiers the docs pipeline understands, in increasing order of stability. */
const TIERS = ['experimental', 'developerPreview', 'publicApi'];

/**
 * The packages Angular's SemVer, release schedule and deprecation policy apply to, per
 * `contributing-docs/public-api-surface.md`. Goldens exist for packages outside this list
 * (`compiler-cli`, `localize`); those record the surface without promising stability for it.
 */
const SEMVER_COVERED = new Set([
  '@angular/animations',
  '@angular/common',
  '@angular/core',
  '@angular/elements',
  '@angular/forms',
  '@angular/platform-browser-dynamic',
  '@angular/platform-browser',
  '@angular/platform-server',
  '@angular/router',
  '@angular/service-worker',
  '@angular/upgrade',
]);

/**
 * Coverage is a property of the package, not of the entry point: the policy excludes "any
 * file/import paths within our package except for the `/`, `/testing` and `/bundles/*` and other
 * documented package entry-points", so a documented secondary entry point of a covered package is
 * covered too.
 *
 * API Extractor names secondary entry points with an underscore — `@angular/common_http` for
 * `@angular/common/http` — so the package is the segment before the first underscore.
 */
function isSemVerCovered(entryPointName) {
  const withoutScope = entryPointName.replace(/^@angular\//, '');
  return SEMVER_COVERED.has(`@angular/${withoutScope.split('_')[0]}`);
}

// --- goldens ---------------------------------------------------------------------------------

/** `// @public @deprecated (undocumented)` — API Extractor's release-tag line. */
const RELEASE_TAG_LINE = /^\/\/ (@[^\n]*)$/;
/** The declaration that follows a release-tag line. */
const DECLARATION =
  /^export (?:declare )?(?:abstract )?(class|interface|function|const|let|var|type|enum|namespace)\s+([A-Za-z_$ɵ][\w$ɵ]*)/;
/**
 * API Extractor also emits bare re-exports — `export { NgForOf as NgFor }` — for symbols that
 * reach the entry point under a second name. They are part of the surface, so they are counted,
 * with the exported (right-hand) name.
 */
const REEXPORT = /^export \{\s*([A-Za-z_$ɵ][\w$ɵ]*)(?:\s+as\s+([A-Za-z_$ɵ][\w$ɵ]*))?\s*\}/;

function* goldenFiles(dir) {
  for (const entry of readdirSync(dir, {withFileTypes: true})) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) yield* goldenFiles(full);
    else if (entry.name.endsWith('.api.md')) yield full;
  }
}

function readGoldens() {
  const entryPoints = [];
  for (const file of goldenFiles(GOLDENS)) {
    const rel = relative(GOLDENS, file).split(sep).join('/');
    const source = readFileSync(file, 'utf8');
    const lines = source.split('\n');

    // `@angular/core` from the report header, falling back to the path.
    const name = source.match(/^## API Report File for "([^"]+)"/m)?.[1] ?? rel;

    const symbols = [];
    let pendingTags = null;
    for (const line of lines) {
      const tagMatch = RELEASE_TAG_LINE.exec(line);
      if (tagMatch) {
        pendingTags = tagMatch[1];
        continue;
      }
      const decl = DECLARATION.exec(line);
      const reexport = decl ? null : REEXPORT.exec(line);
      if (decl || reexport) {
        const kind = decl ? decl[1] : 're-export';
        const name = decl ? decl[2] : (reexport[2] ?? reexport[1]);
        symbols.push({
          kind,
          name,
          tags: pendingTags ?? '',
          deprecated: (pendingTags ?? '').includes('@deprecated'),
          undocumented: (pendingTags ?? '').includes('(undocumented)'),
          private: name.startsWith('ɵ'),
        });
      }
      if (line.trim() !== '' && !tagMatch) pendingTags = null;
    }
    entryPoints.push({
      name,
      // Goldens exist both for real npm entry points and for internal surfaces that are worth
      // review but are not importable — the error-code enums, the `ng.*` debug utilities, the
      // compiler options. Only the former are named after a package.
      isEntryPoint: name.startsWith('@angular/'),
      file: relative(REPO_ROOT, file).split(sep).join('/'),
      symbols,
    });
  }
  return entryPoints.sort((a, b) => a.name.localeCompare(b.name));
}

// --- source JSDoc tags -----------------------------------------------------------------------

/**
 * A JSDoc block immediately followed by an exported declaration.
 *
 * The comment body is `(?:[^*]|\*(?!\/))*` rather than `[\s\S]*?` on purpose: a lazy quantifier
 * backtracks across `*​/` when the tail fails to match, which silently merges the *previous*
 * comment into this one and attributes its tags to the wrong symbol.
 */
const DOC_BLOCK = new RegExp(
  String.raw`/\*\*((?:[^*]|\*(?!/))*)\*/\s*` +
    String.raw`(?:@\w+\((?:[^()]|\([^()]*\))*\)\s*)*` +
    String.raw`export\s+(?:declare\s+)?(?:abstract\s+)?(?:async\s+)?` +
    String.raw`(class|interface|function\*?|const|let|var|type|enum|namespace)\s+([A-Za-z_$ɵ][\w$ɵ]*)`,
  'g',
);

function* sourceFiles(dir) {
  let entries;
  try {
    entries = readdirSync(dir, {withFileTypes: true});
  } catch {
    return;
  }
  for (const entry of entries) {
    if (entry.name.startsWith('.')) continue;
    const full = join(dir, entry.name);
    if (entry.isDirectory()) {
      if (['node_modules', 'test', 'tests'].includes(entry.name)) continue;
      yield* sourceFiles(full);
    } else if (entry.name.endsWith('.ts') && !entry.name.endsWith('.d.ts')) {
      if (entry.name.includes('_spec.') || entry.name.includes('.spec.')) continue;
      yield full;
    }
  }
}

/** Extracts the tags of interest from a JSDoc comment body. */
function tagsOf(body) {
  const found = new Map();
  for (const tag of [...TIERS, 'deprecated']) {
    const m = new RegExp(`@${tag}\\b([^\\n@]*)`).exec(body);
    if (m) {
      // The docs pipeline reads the version as the first number in the tag comment.
      found.set(tag, m[1].match(/\d+(\.\d+)?/)?.[0]);
    }
  }
  return found;
}

function readSourceTags() {
  /** @type {Map<string, {tiers: string[], deprecatedVersion: string|undefined, file: string, hasDeprecated: boolean}>} */
  const byName = new Map();
  for (const pkg of readdirSync(PACKAGES, {withFileTypes: true})) {
    if (!pkg.isDirectory()) continue;
    for (const file of sourceFiles(join(PACKAGES, pkg.name))) {
      const rel = relative(REPO_ROOT, file).split(sep).join('/');
      if (rel.includes('/schematics/') || rel.includes('/examples/')) continue;
      const source = readFileSync(file, 'utf8');
      for (const m of source.matchAll(DOC_BLOCK)) {
        const tags = tagsOf(m[1]);
        if (tags.size === 0) continue;
        const name = m[3];
        if (!byName.has(name)) {
          byName.set(name, {
            tiers: TIERS.filter((t) => tags.has(t)),
            deprecatedVersion: tags.get('deprecated'),
            hasDeprecated: tags.has('deprecated'),
            file: rel,
            package: pkg.name,
          });
        }
      }
    }
  }
  return byName;
}

// --- report ----------------------------------------------------------------------------------

function main() {
  mkdirSync(OUT_DIR, {recursive: true});
  const entryPoints = readGoldens();
  const sourceTags = readSourceTags();
  const problems = [];

  // A symbol sitting in two tiers at once is a contradiction: the tiers describe mutually
  // exclusive levels of support. Anything else here is reported, not failed — in particular a
  // deprecation without a version is common in this repository and no policy requires one.
  for (const [name, info] of sourceTags) {
    if (info.tiers.length > 1) {
      problems.push(
        `\`${name}\` (${info.file}) declares more than one stability tier: ` +
          info.tiers.map((t) => `@${t}`).join(', '),
      );
    }
  }

  const allSymbols = entryPoints.flatMap((e) => e.symbols);
  const publicSymbols = allSymbols.filter((s) => !s.private);
  const privateSymbols = allSymbols.filter((s) => s.private);

  const lines = [
    '<!--',
    '  GENERATED FILE — do not edit by hand.',
    '  Regenerate with: node docs/codebase-map/tools/analyze-api-surface.mjs',
    '-->',
    '',
    '# Public API surface',
    '',
    'Measured from the API goldens in `goldens/public-api/`, which are generated from the built',
    '`.d.ts` and reviewed on every change, plus the stability tags in source. See',
    '[`../21-api-surface.md`](../21-api-surface.md) for what the numbers mean.',
    '',
    '## npm entry points',
    '',
    `${entryPoints.filter((e) => e.isEntryPoint).length} entry points across ` +
      `${entryPoints.length} goldens, ${allSymbols.length} exported declarations ` +
      `(${publicSymbols.length} public, ${privateSymbols.length} \`ɵ\`-prefixed).`,
    '',
    'The **SemVer** column is package-level, from `contributing-docs/public-api-surface.md`.',
    '',
    '| Entry point | SemVer | Declarations | `ɵ` private | Deprecated | Undocumented |',
    '| --- | :-: | ---: | ---: | ---: | ---: |',
  ];

  for (const e of entryPoints.filter((e) => e.isEntryPoint)) {
    lines.push(
      `| \`${e.name.replace(/_/g, '/')}\` | ${isSemVerCovered(e.name) ? 'yes' : 'no'} | ` +
        `${e.symbols.length} | ${e.symbols.filter((s) => s.private).length} | ` +
        `${e.symbols.filter((s) => s.deprecated).length} | ` +
        `${e.symbols.filter((s) => s.undocumented).length} |`,
    );
  }

  lines.push(
    '',
    '## Internal-surface goldens',
    '',
    'Not importable API. These track surfaces the team wants reviewed on every change anyway —',
    'the runtime and compiler error codes, the `ng.*` debug utilities, the compiler options.',
    '',
    '| Golden | Declarations | Tracks |',
    '| --- | ---: | --- |',
  );
  for (const e of entryPoints.filter((e) => !e.isEntryPoint)) {
    lines.push(`| \`${e.name}\` | ${e.symbols.length} | \`${e.file}\` |`);
  }

  // Kind breakdown.
  const kinds = new Map();
  for (const s of allSymbols) kinds.set(s.kind, (kinds.get(s.kind) ?? 0) + 1);
  lines.push('', '## By declaration kind', '', '| Kind | Count |', '| --- | ---: |');
  for (const [kind, n] of [...kinds].sort((a, b) => b[1] - a[1])) {
    lines.push(`| \`${kind}\` | ${n} |`);
  }

  // Stability tiers from source.
  const tierCounts = new Map(TIERS.map((t) => [t, 0]));
  for (const info of sourceTags.values()) {
    for (const t of info.tiers) tierCounts.set(t, tierCounts.get(t) + 1);
  }
  const deprecated = [...sourceTags].filter(([, i]) => i.hasDeprecated);
  lines.push(
    '',
    '## Stability tiers declared in source',
    '',
    'These come from JSDoc and are read by the docs pipeline, not by the goldens.',
    '',
    '| Tag | Symbols |',
    '| --- | ---: |',
  );
  for (const t of TIERS) lines.push(`| \`@${t}\` | ${tierCounts.get(t)} |`);
  lines.push(`| \`@deprecated\` | ${deprecated.length} |`);

  // Non-stable APIs, listed — this is the set most likely to change.
  const goldenNames = new Set(allSymbols.map((s) => s.name));
  for (const tier of ['experimental', 'developerPreview']) {
    const list = [...sourceTags].filter(([, i]) => i.tiers.includes(tier));
    lines.push(
      '',
      `## \`@${tier}\` symbols (${list.length})`,
      '',
      'Not subject to the breaking-change policy (`contributing-docs/dev_preview_and_experimental.md`).',
      'The "in a golden" column matters: the goldens record every release tag as `@public`, so a',
      'symbol listed there looks stable in the reviewed API surface regardless of this tier.',
      '',
      '| Symbol | In a golden | Declared in |',
      '| --- | :-: | --- |',
    );
    for (const [name, info] of list.sort((a, b) => a[0].localeCompare(b[0]))) {
      lines.push(`| \`${name}\` | ${goldenNames.has(name) ? 'yes' : 'no'} | \`${info.file}\` |`);
    }
  }

  // Deprecations, grouped by the version they were deprecated in.
  const byVersion = new Map();
  for (const [name, info] of deprecated) {
    const key = info.deprecatedVersion ?? '(no version)';
    if (!byVersion.has(key)) byVersion.set(key, []);
    byVersion.get(key).push(name);
  }
  const withoutVersion = byVersion.get('(no version)')?.length ?? 0;
  lines.push(
    '',
    `## Deprecations (${deprecated.length})`,
    '',
    'Grouped by the version in the `@deprecated` tag, which the docs manifest reads as the first',
    `number in the tag comment. ${withoutVersion} of them state no version, so their manifest`,
    'entry records `version: undefined`; no policy in this repository requires one.',
    '',
    '| Since | Symbols |',
    '| --- | --- |',
  );
  const versionKeys = [...byVersion.keys()].sort((a, b) => {
    if (a === '(no version)') return 1;
    if (b === '(no version)') return -1;
    return parseFloat(b) - parseFloat(a);
  });
  for (const v of versionKeys) {
    const names = byVersion.get(v).sort();
    lines.push(`| ${v} | ${names.map((n) => `\`${n}\``).join(', ')} |`);
  }

  writeFileSync(join(OUT_DIR, 'api-surface.md'), lines.join('\n') + '\n', 'utf8');

  console.log(
    `goldens: ${entryPoints.length} entry points, ${allSymbols.length} declarations ` +
      `(${privateSymbols.length} ɵ-private, ${allSymbols.filter((s) => s.deprecated).length} deprecated)`,
  );
  console.log(
    `source tags: ` +
      TIERS.map((t) => `@${t}=${tierCounts.get(t)}`).join(', ') +
      `, @deprecated=${deprecated.length}`,
  );
  if (problems.length) {
    console.error(`\n${problems.length} stability problem(s):`);
    for (const p of problems) console.error(`  - ${p}`);
    process.exitCode = 1;
  } else {
    console.log('all stability conventions hold.');
  }
}

main();
